import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"Layered・Clean・Hexagonal — 境界と依存の向き","description":"","frontmatter":{"title":"Layered・Clean・Hexagonal — 境界と依存の向き","study":{"source":"設計の手帖","kind":"本文","status":"既存原稿","summary":"パターンがクラスの連携を扱うなら、アーキテクチャはシステムの大きな境界を扱います。"}},"headers":[],"relativePath":"design/notebook/architecture.md","filePath":"design/notebook/architecture.md"}'),n={name:"design/notebook/architecture.md"};function o(l,e,d,s,c,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="layered・clean・hexagonal-—-境界と依存の向き" tabindex="-1">Layered・Clean・Hexagonal — 境界と依存の向き <a class="header-anchor" href="#layered・clean・hexagonal-—-境界と依存の向き" aria-label="Permalink to &quot;Layered・Clean・Hexagonal — 境界と依存の向き&quot;">​</a></h1><p>パターンがクラスの連携を扱うなら、アーキテクチャはシステムの大きな境界を扱います。</p><p>03 · アプリ全体を設計する / レイヤーとアーキテクチャ / Keep the core independent / 応用 / 12分</p><p>タグ: Layered / Clean Architecture / Hexagonal / Ports and Adapters / Vertical Slice</p><h2 id="layered-関心事ごとに層を分ける" tabindex="-1">Layered：関心事ごとに層を分ける <a class="header-anchor" href="#layered-関心事ごとに層を分ける" aria-label="Permalink to &quot;Layered：関心事ごとに層を分ける&quot;">​</a></h2><div><p>典型例は UI → Application → Data Access です。入口、処理の調整、保存を分けると場所が見つけやすくなります。ただし、Application が DB 実装へ直接依存すると、DB の変更や準備が業務テストに影響します。論理的な層（Layer）と、別サーバーへ配置する単位（Tier）は同義ではありません。</p></div><h2 id="clean-ソースコードの依存を中心へ向ける" tabindex="-1">Clean：ソースコードの依存を中心へ向ける <a class="header-anchor" href="#clean-ソースコードの依存を中心へ向ける" aria-label="Permalink to &quot;Clean：ソースコードの依存を中心へ向ける&quot;">​</a></h2><div><p>中心に業務ルールと必要な契約を置き、UI や DB 実装が中心の契約を利用・実装します。実行時には業務処理から DB へ呼び出しても、ソース上の型参照は外側から内側へ向けられます。実行順と依存の向きは別です。</p><div class="dependency-diagram"><div><span>UI</span><b>OrderController</b><small>入力を受け取る</small></div><i>→</i><div class="diagram-core"><span>APPLICATION CORE</span><b>PlaceOrderUseCase</b><small>IOrderRepository を定義</small></div><i>←</i><div><span>INFRASTRUCTURE</span><b>SqlOrderRepository</b><small>契約を実装する</small></div></div><p>図の矢印はソースコード上の依存です。起動時の組み立て場所は、具体実装を知る必要があります。Domain / Application / Infrastructure / Presentation はよく使う区分ですが、フォルダを作るだけでは依存は制限されません。C# はプロジェクト参照、C++ はヘッダーとビルドターゲットの関係を確認します。</p></div><h2 id="hexagonal-入口と出口を-port-として扱う" tabindex="-1">Hexagonal：入口と出口を Port として扱う <a class="header-anchor" href="#hexagonal-入口と出口を-port-として扱う" aria-label="Permalink to &quot;Hexagonal：入口と出口を Port として扱う&quot;">​</a></h2><div><p>ユースケースを呼ぶ入口と、保存・通知など外へ求める出口を Port とし、UI や SQL を Adapter として取り付けます。Clean、Onion、Hexagonal は背景や表現に違いがありますが、中心を技術的な詳細から守るという共通点があります。厳密に同一の設計手法ではありません。</p></div><h2 id="vertical-slice-変更される機能の単位でまとめる" tabindex="-1">Vertical Slice：変更される機能の単位でまとめる <a class="header-anchor" href="#vertical-slice-変更される機能の単位でまとめる" aria-label="Permalink to &quot;Vertical Slice：変更される機能の単位でまとめる&quot;">​</a></h2><div><p><code>Orders/Create</code> に入力・処理・結果をまとめ、<code>Orders/List</code> と分けるような構成です。層ごとに多数のフォルダを横断せず、機能の変更を近くに置けます。共有すべき業務ルールまでコピーしないことが大切です。Slice の内側でレイヤーやドメインモデルを使うこともできます。</p><aside class="article-note"><strong>最初の規模の目安</strong><p>小さなツールは関数と数個の型から始めます。外部 I/O と計算を分けるだけでも効果があります。マイクロサービスや多数のプロジェクトへ分割することは、独立した判断です。</p></aside></div><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><p>DB を取り替えるとき、どのプロジェクトやヘッダーまで変更が広がりますか？</p><h2 id="この章の参考資料" tabindex="-1">この章の参考資料 <a class="header-anchor" href="#この章の参考資料" aria-label="Permalink to &quot;この章の参考資料&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/modern-web-apps-azure-architecture/common-web-application-architectures" target="_blank" rel="noreferrer">Common web application architectures</a> — Microsoft Learn。レイヤーと、Application Core へ向ける依存関係。</li></ul><p><a href="/study/design/naming.html">クラス名辞典</a> / <a href="/study/design/pattern-index.html">パターン一覧</a> / <a href="/study/design/notebook-references.html">手帖の参考資料</a></p>',17)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
